select.if:

SELECT mber_id AS id
  FROM NGNRLMBER
 WHERE mber_nm = #{name}
   AND mber_email_adres = #{email}
   AND mber_sttus = 'P'


SELECT ENTRPRS_MBER_ID AS id
  FROM NENTRPRSMBER
 WHERE cmpny_nm = #{name}
   AND applcnt_email_adres = #{email}
   AND entrprs_mber_sttus = 'P'


SELECT emplyr_id AS id
  FROM NEMPLYRINFO
 WHERE user_nm = #{name}
   AND email_adres = #{email}
   AND emplyr_sttus_code = 'P'


SELECT password AS password
  FROM NGNRLMBER
 WHERE mber_id = #{id}
   AND mber_nm = #{name}
   AND mber_email_adres = #{email}
   AND password_hint = #{passwordHint}
   AND password_cnsr = #{passwordCnsr}
   AND mber_sttus = 'P'

SELECT entrprs_mber_password AS password
  FROM NENTRPRSMBER
 WHERE ENTRPRS_MBER_ID = #{id}
   AND cmpny_nm = #{name}
   AND applcnt_email_adres = #{email}
   AND entrprs_mber_password_hint = #{passwordHint}
   AND entrprs_mber_password_cnsr = #{passwordCnsr}
   AND entrprs_mber_sttus = 'P'

SELECT password AS password
  FROM NEMPLYRINFO
 WHERE emplyr_id = #{id}
   AND user_nm = #{name}
   AND email_adres = #{email}
   AND password_hint = #{passwordHint}
   AND password_cnsr = #{passwordCnsr}
   AND emplyr_sttus_code = 'P'

update.if:
UPDATE NGNRLMBER
   SET password = #{password}
     , CHG_PWD_LAST_PNTTM = NOW()
 WHERE mber_id = #{id}

UPDATE NENTRPRSMBER
   SET entrprs_mber_password = #{password}
     , CHG_PWD_LAST_PNTTM = NOW()
 WHERE ENTRPRS_MBER_ID = #{id}

UPDATE NEMPLYRINFO
   SET password = #{password}
     , CHG_PWD_LAST_PNTTM = NOW()
 WHERE emplyr_id = #{id}

select.if:

SELECT COALESCE(DATE_PART('day', NOW() - CHG_PWD_LAST_PNTTM),0)
  FROM NGNRLMBER
 WHERE mber_id = #{id}


SELECT COALESCE(DATE_PART('day', NOW() - CHG_PWD_LAST_PNTTM),0)
  FROM NENTRPRSMBER
 WHERE ENTRPRS_MBER_ID = #{id}


SELECT COALESCE(DATE_PART('day', NOW() - CHG_PWD_LAST_PNTTM),0)
  FROM NEMPLYRINFO
 WHERE emplyr_id = #{id}
